function validate([arr, k]) {
  const n = arr.length;
  if (n < 1 || n > 500) return 'arr needs 1 to 500 values.';
  if (arr.some(v => v < 0 || v > 1000000000)) return 'Each value is between 0 and 10^9.';
  if (k < 1 || k > n) return 'k is between 1 and arr.length.';
  // The answer is at most max(arr) * n; only compute it when that bound is too big.
  if (Math.max(...arr) * n <= 2147483647) return null;
  const dp = new Array(n + 1).fill(0);
  for (let i = 1; i <= n; i++) {
    let top = 0;
    for (let s = 1; s <= Math.min(k, i); s++) { top = Math.max(top, arr[i - s]); dp[i] = Math.max(dp[i], dp[i - s] + top * s); }
  }
  return dp[n] > 2147483647 ? 'The answer must fit in a 32-bit signed integer.' : null;
}

