function maxSumAfterPartitioning(arr, k) {
  const n = arr.length;
  const dp = new Array(n + 1).fill(0);

  for (let i = 1; i <= n; i++) {
    let biggest = 0;
    for (let size = 1; size <= Math.min(k, i); size++) {
      biggest = Math.max(biggest, arr[i - size]);
      dp[i] = Math.max(dp[i], dp[i - size] + biggest * size);
    }
  }
  return dp[n];
}

