function maxSumAfterPartitioning(arr, k) {
  const n = arr.length;
  const pieceValue = (from, to) => Math.max(...arr.slice(from, to)) * (to - from);
  if (n <= 14) {
    // Try every set of cut positions; bit c set means a cut after index c.
    let best = 0;
    for (let mask = 0; mask < (1 << (n - 1)); mask++) {
      let start = 0, total = 0, ok = true;
      for (let c = 0; c < n; c++) {
        if (c === n - 1 || (mask >> c) & 1) {
          if (c + 1 - start > k) { ok = false; break; }
          total += pieceValue(start, c + 1);
          start = c + 1;
        }
      }
      if (ok) best = Math.max(best, total);
    }
    return best;
  }
  // Longer arrays: choose the first piece, then solve the rest (memoised by its start).
  const memo = new Map();
  const solve = (start) => {
    if (start === n) return 0;
    if (memo.has(start)) return memo.get(start);
    let best = 0;
    for (let end = start + 1; end <= Math.min(n, start + k); end++) best = Math.max(best, pieceValue(start, end) + solve(end));
    memo.set(start, best);
    return best;
  };
  for (let start = n; start >= 0; start--) solve(start);
  return solve(0);
}

