function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = 500;
    const arr = Array.from({ length: n }, () => int(0, 4000000));
    return [arr, int(1, 60)];
  }
  const n = int(1, 10);
  const tops = [3, 20, 1000, 200000000];
  const top = tops[int(0, tops.length - 1)];
  const arr = Array.from({ length: n }, () => int(0, top));
  return [arr, int(1, n)];
}
